-- ============================================
-- LUMA — Thème 8 : MOYEN 3/3 x4 — Résoudre une énigme de temple
-- ============================================


update scenarios set content = '{"characters": {"voice": "la voix ancienne", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "narrator", "text": "You enter an ancient temple. A voice echoes: ''Three riddles guard the way. Answer wisely.''", "text_fr": "Vous entrez dans un temple ancien. Une voix résonne : ''Trois énigmes gardent le chemin. Répondez sagement.''", "choices": [{"text": "I''m ready. Speak your first riddle.", "text_fr": "Je suis prêt. Dites votre première énigme.", "next": "n2"}]}, "n2": {"speaker": "voice", "text": "Riddle one: I speak without a mouth and hear without ears. I have no body, but I come alive with wind. What am I?", "text_fr": "Énigme un : Je parle sans bouche et entends sans oreilles. Je n''ai pas de corps, mais je prends vie avec le vent. Que suis-je ?", "choices": [{"text": "An echo.", "text_fr": "Un écho.", "next": "n3"}, {"text": "A ghost, perhaps?", "text_fr": "Un fantôme, peut-être ?", "next": "n3b"}]}, "n3": {"speaker": "voice", "text": "Correct! The stone door shifts slightly. Onward, to the second riddle.", "text_fr": "Correct ! La porte de pierre se déplace légèrement. En avant, vers la deuxième énigme.", "choices": [{"text": "I''m ready for the next one.", "text_fr": "Je suis prêt pour la suivante.", "next": "n4"}]}, "n3b": {"speaker": "voice", "text": "Incorrect. Think again — what lives only through wind, without form?", "text_fr": "Incorrect. Réfléchissez encore — qu''est-ce qui vit seulement à travers le vent, sans forme ?", "choices": [{"text": "An echo! That must be it.", "text_fr": "Un écho ! Ça doit être ça.", "next": "n4"}]}, "n4": {"speaker": "voice", "text": "Riddle two: The more you take, the more you leave behind. What am I?", "text_fr": "Énigme deux : Plus tu en prends, plus tu en laisses derrière toi. Que suis-je ?", "choices": [{"text": "Footsteps.", "text_fr": "Des pas.", "next": "n5"}, {"text": "Time, perhaps?", "text_fr": "Le temps, peut-être ?", "next": "n5b"}]}, "n5": {"speaker": "voice", "text": "Correct again! Impressive, traveler. The second door opens.", "text_fr": "Encore correct ! Impressionnant, voyageur. La deuxième porte s''ouvre.", "choices": [{"text": "On to the final riddle, then.", "text_fr": "Vers l''énigme finale, alors.", "next": "n6"}]}, "n5b": {"speaker": "voice", "text": "Close, but not quite. Think of something you leave more of as you take more steps.", "text_fr": "Proche, mais pas tout à fait. Pensez à quelque chose que vous laissez plus en faisant plus de pas.", "choices": [{"text": "Ah, footsteps! Of course.", "text_fr": "Ah, des pas ! Bien sûr.", "next": "n6"}]}, "n6": {"speaker": "voice", "text": "Final riddle: I am not alive, but I grow. I don''t have lungs, but I need air. What am I?", "text_fr": "Énigme finale : Je ne suis pas vivant, mais je grandis. Je n''ai pas de poumons, mais j''ai besoin d''air. Que suis-je ?", "choices": [{"text": "Fire.", "text_fr": "Le feu.", "next": "n7"}, {"text": "Could it be some kind of crystal?", "text_fr": "Ça pourrait être une sorte de cristal ?", "next": "n7b"}]}, "n7": {"speaker": "voice", "text": "Excellent! You have proven your wisdom, traveler. The final door opens.", "text_fr": "Excellent ! Vous avez prouvé votre sagesse, voyageur. La porte finale s''ouvre.", "choices": [{"text": "(Step through the final door, heart pounding with anticipation.)", "text_fr": "(Franchis la porte finale, le cœur battant d''anticipation.)", "next": "n8"}]}, "n7b": {"speaker": "voice", "text": "Not quite — think of something that consumes air to grow, yet has no life of its own.", "text_fr": "Pas tout à fait — pensez à quelque chose qui consomme de l''air pour grandir, mais n''a pas de vie propre.", "choices": [{"text": "Fire! It needs air to burn and grow.", "text_fr": "Le feu ! Il a besoin d''air pour brûler et grandir.", "next": "n8"}]}, "n8": {"speaker": "narrator", "text": "(Beyond the door, a chamber filled with golden light and an ancient treasure awaits.)", "text_fr": "(Au-delà de la porte, une chambre remplie de lumière dorée et un trésor ancien attend.)", "choices": [{"text": "Approach the treasure with reverence and care.", "text_fr": "Approche-toi du trésor avec révérence et précaution.", "next": "n9"}]}, "n9": {"speaker": "voice", "text": "You have earned this treasure through wisdom, not force. Take it, worthy one.", "text_fr": "Vous avez gagné ce trésor par la sagesse, non par la force. Prenez-le, digne voyageur.", "choices": [{"text": "I''m honored by this trial. Thank you, ancient temple.", "text_fr": "Je suis honoré par cette épreuve. Merci, temple ancien.", "next": "end_solved"}]}, "end_solved": {"speaker": "voice", "text": "Go now, wise one, and may your wisdom light the path ahead.", "text_fr": "Allez maintenant, sage voyageur, et que votre sagesse éclaire le chemin à venir.", "end": true, "ending_label": "Énigmes du temple résolues avec sagesse 🏛️🧠"}}}'::jsonb, is_playable = true
where title = 'Résoudre une énigme de temple'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
